package com.retail.sales;
import java.math.BigDecimal;
import java.util.*;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import com.retail.common.security.BranchAccess;
@RestController @RequestMapping("/api/v1/sales/{saleId}/refunds")
public class RefundController {
 private final JdbcTemplate jdbc;private final BranchAccess access;public RefundController(JdbcTemplate j,BranchAccess a){jdbc=j;access=a;}
 public record Line(@NotNull UUID saleLineId,@Min(1) int quantity,boolean restock){}public record Request(@NotBlank String reason,@NotEmpty List<@Valid Line> lines){}
 @PostMapping @Transactional @PreAuthorize("hasAnyRole('SUPER_ADMIN','BRANCH_MANAGER','CASHIER')") public Map<String,Object> request(@PathVariable UUID saleId,@Valid @RequestBody Request r,Authentication a){var sale=jdbc.queryForMap("select * from sales where id=?",saleId);access.requireBranch(a,(UUID)sale.get("branch_id"));UUID id=UUID.randomUUID(),actor=jdbc.queryForObject("select id from users where username=?",UUID.class,a.getName());String no="RF-"+id.toString().substring(0,12).toUpperCase(Locale.ROOT);jdbc.update("insert into refunds(id,refund_no,sale_id,status,reason,created_by) values (?,?,?,'PENDING',?,?)",id,no,saleId,r.reason(),actor);for(Line line:r.lines()){var sold=jdbc.queryForMap("select * from sale_lines where id=? and sale_id=?",line.saleLineId(),saleId);int refunded=jdbc.queryForObject("select coalesce(sum(rl.quantity),0) from refund_lines rl join refunds rf on rf.id=rl.refund_id where rl.sale_line_id=? and rf.status in ('PENDING','APPROVED')",Integer.class,line.saleLineId());if(refunded+line.quantity()>(Integer)sold.get("quantity"))throw new IllegalArgumentException("Refund quantity exceeds sold quantity");BigDecimal amount=((BigDecimal)sold.get("line_total")).multiply(BigDecimal.valueOf(line.quantity())).divide(BigDecimal.valueOf((Integer)sold.get("quantity")),4,java.math.RoundingMode.HALF_EVEN);jdbc.update("insert into refund_lines(refund_id,sale_line_id,quantity,amount,restock) values (?,?,?,?,?)",id,line.saleLineId(),line.quantity(),amount,line.restock());}return Map.of("id",id,"refundNo",no,"status","PENDING");}
 @PostMapping("/{refundId}/approve") @Transactional @PreAuthorize("hasAnyRole('SUPER_ADMIN','BRANCH_MANAGER')") public Map<String,Object> approve(@PathVariable UUID saleId,@PathVariable UUID refundId,Authentication a){var refund=jdbc.queryForMap("select * from refunds where id=? and sale_id=? for update",refundId,saleId);if(!"PENDING".equals(refund.get("status")))throw new IllegalStateException("Refund is not pending");var sale=jdbc.queryForMap("select * from sales where id=?",saleId);access.requireBranch(a,(UUID)sale.get("branch_id"));UUID actor=jdbc.queryForObject("select id from users where username=?",UUID.class,a.getName());for(var line:jdbc.queryForList("select rl.*,sl.product_id from refund_lines rl join sale_lines sl on sl.id=rl.sale_line_id where rl.refund_id=? for update",refundId)){if(Boolean.TRUE.equals(line.get("restock"))){UUID branch=(UUID)sale.get("branch_id"),product=(UUID)line.get("product_id");UUID location=jdbc.queryForObject("select id from locations where branch_id=? and type='BRANCH'",UUID.class,branch);int qty=(Integer)line.get("quantity");jdbc.update("insert into stock_balances(location_id,product_id,quantity) values (?,?,?) on conflict(location_id,product_id) do update set quantity=stock_balances.quantity+excluded.quantity,version=stock_balances.version+1",location,product,qty);jdbc.update("insert into stock_movements(location_id,product_id,quantity_delta,movement_type,source_type,source_id,source_line_id,actor_id) values (?,?,?,'REFUND_RESTOCK','REFUND',?,?,?)",location,product,qty,refundId,line.get("id"),actor);}}jdbc.update("update refunds set status='APPROVED',approved_by=? where id=?",actor,refundId);jdbc.update("update sales set status='PARTIALLY_REFUNDED' where id=?",saleId);return Map.of("id",refundId,"status","APPROVED");}
}
